package main

import (
	"bufio"
	"fmt"
	"io"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"
)

const (
	versionStr = "loop 0.6.1"
	authorStr  = "Rich Jones <miserlou@gmail.com>"
	aboutStr   = "UNIX's missing `loop` command"
)

// progName returns the executable's base name used in USAGE and error messages.
func progName() string {
	if len(os.Args) == 0 {
		return "executable"
	}
	return filepath.Base(os.Args[0])
}

// OptionSpec describes a CLI option or flag.
type OptionSpec struct {
	Short   byte   // e.g. 'n' or 0
	Long    string // e.g. "num"
	ValName string // e.g. "num" (empty if boolean flag)
	Help    string
	Default string
	HasDef  bool
	// For ordering in help & USAGE
}

// Option specs (flags first, then options). Order matches original help text.
var flagSpecs = []OptionSpec{
	{Short: 'D', Long: "error-duration", Help: "Exit with timeout error code on duration"},
	{Short: 'h', Long: "help", Help: "Prints help information"},
	{Short: 'l', Long: "only-last", Help: "Only print the output of the last execution of the command"},
	{Short: 'i', Long: "stdin", Help: "Read from standard input"},
	{Long: "summary", Help: "Provide a summary"},
	{Short: 'C', Long: "until-changes", Help: "Keep going until the output changes"},
	{Short: 'f', Long: "until-fail", Help: "Keep going until the command exit status is non-zero"},
	{Short: 'S', Long: "until-same", Help: "Keep going until the output changes"},
	{Short: 's', Long: "until-success", Help: "Keep going until the command exit status is zero"},
	{Short: 'V', Long: "version", Help: "Prints version information"},
}

var optionSpecs = []OptionSpec{
	{Short: 'b', Long: "count-by", ValName: "count_by", Help: "Amount to increment the counter by", Default: "1", HasDef: true},
	{Short: 'e', Long: "every", ValName: "every", Help: "How often to iterate. ex., 5s, 1h1m1s1ms1us", Default: "1us", HasDef: true},
	{Long: "for", ValName: "ffor", Help: "A comma-separated list of values, placed into 4ITEM. ex., red,green,blue"},
	{Short: 'd', Long: "for-duration", ValName: "for_duration", Help: "Keep going until the duration has elapsed (example 1m30s)"},
	{Short: 'n', Long: "num", ValName: "num", Help: "Number of iterations to execute"},
	{Short: 'o', Long: "offset", ValName: "offset", Help: "Amount to offset the initial counter by", Default: "0", HasDef: true},
	{Short: 'c', Long: "until-contains", ValName: "until_contains", Help: "Keep going until the output contains this string"},
	{Short: 'r', Long: "until-error", ValName: "until_error", Help: "Keep going until the command exit status is the value given"},
	{Short: 'm', Long: "until-match", ValName: "until_match", Help: "Keep going until the output matches this regular expression"},
	{Short: 't', Long: "until-time", ValName: "until_time", Help: `Keep going until a future time, ex. "2018-04-20 04:20:00" (Times in UTC.)`},
}

// Parsed holds parsed CLI arguments.
type Parsed struct {
	flags   map[string]bool
	options map[string]string
	input   []string
	// Track which options/flags were explicitly provided on the CLI.
	provided map[string]bool
}

func newParsed() *Parsed {
	p := &Parsed{
		flags:    make(map[string]bool),
		options:  make(map[string]string),
		provided: make(map[string]bool),
	}
	for _, o := range optionSpecs {
		if o.HasDef {
			p.options[o.Long] = o.Default
		}
	}
	return p
}

func findFlagByShort(c byte) *OptionSpec {
	for i := range flagSpecs {
		if flagSpecs[i].Short == c {
			return &flagSpecs[i]
		}
	}
	return nil
}
func findFlagByLong(s string) *OptionSpec {
	for i := range flagSpecs {
		if flagSpecs[i].Long == s {
			return &flagSpecs[i]
		}
	}
	return nil
}
func findOptByShort(c byte) *OptionSpec {
	for i := range optionSpecs {
		if optionSpecs[i].Short == c {
			return &optionSpecs[i]
		}
	}
	return nil
}
func findOptByLong(s string) *OptionSpec {
	for i := range optionSpecs {
		if optionSpecs[i].Long == s {
			return &optionSpecs[i]
		}
	}
	return nil
}

// renderHelp constructs the --help text.
func renderHelp() string {
	var sb strings.Builder
	sb.WriteString(versionStr + "\n")
	sb.WriteString(authorStr + "\n")
	sb.WriteString(aboutStr + "\n\n")
	sb.WriteString("USAGE:\n")
	sb.WriteString("    " + progName() + " [FLAGS] [OPTIONS] [input]...\n\n")
	sb.WriteString("FLAGS:\n")
	// Flags column width: "    -X, --long" with padding
	flagRows := [][2]string{}
	for _, f := range flagSpecs {
		left := "    "
		if f.Short != 0 {
			left += fmt.Sprintf("-%c, ", f.Short)
		} else {
			left += "    "
		}
		left += "--" + f.Long
		flagRows = append(flagRows, [2]string{left, f.Help})
	}
	// Compute max width for column 1 in flags
	flagWidth := 0
	for _, r := range flagRows {
		if len(r[0]) > flagWidth {
			flagWidth = len(r[0])
		}
	}
	// Pad to 4 extra spaces past flagWidth
	for _, r := range flagRows {
		sb.WriteString(r[0])
		sb.WriteString(strings.Repeat(" ", flagWidth-len(r[0])+4))
		sb.WriteString(r[1])
		sb.WriteString("\n")
	}
	sb.WriteString("\nOPTIONS:\n")
	optRows := [][2]string{}
	for _, o := range optionSpecs {
		left := "    "
		if o.Short != 0 {
			left += fmt.Sprintf("-%c, ", o.Short)
		} else {
			left += "    "
		}
		left += "--" + o.Long + " <" + o.ValName + ">"
		rightHelp := o.Help
		if o.HasDef {
			rightHelp += " [default: " + o.Default + "]"
		}
		optRows = append(optRows, [2]string{left, rightHelp})
	}
	optWidth := 0
	for _, r := range optRows {
		if len(r[0]) > optWidth {
			optWidth = len(r[0])
		}
	}
	for _, r := range optRows {
		sb.WriteString(r[0])
		sb.WriteString(strings.Repeat(" ", optWidth-len(r[0])+4))
		sb.WriteString(r[1])
		sb.WriteString("\n")
	}
	sb.WriteString("\nARGS:\n")
	sb.WriteString("    <input>...    The command to be looped\n")
	return sb.String()
}

// printErr prints a clap-style error and exits 1.
func printErr(msg string, usage string) {
	fmt.Fprintf(os.Stderr, "error: %s\n\n", msg)
	if usage != "" {
		fmt.Fprintf(os.Stderr, "USAGE:\n    %s\n\nFor more information try --help\n", usage)
	}
	os.Exit(1)
}

// Parse parses os.Args[1:]. Returns parsed struct or exits on error.
func parseArgs() *Parsed {
	p := newParsed()
	args := os.Args[1:]
	i := 0
	positional := false
	for i < len(args) {
		a := args[i]
		if positional {
			p.input = append(p.input, a)
			i++
			continue
		}
		if a == "--" {
			positional = true
			i++
			continue
		}
		if strings.HasPrefix(a, "--") {
			// long option
			name := a[2:]
			eq := strings.IndexByte(name, '=')
			var val string
			hasVal := false
			if eq >= 0 {
				val = name[eq+1:]
				name = name[:eq]
				hasVal = true
			}
			if fs := findFlagByLong(name); fs != nil {
				if fs.Long == "help" {
					fmt.Print(renderHelp())
					os.Exit(0)
				}
				if fs.Long == "version" {
					fmt.Println(versionStr)
					os.Exit(0)
				}
				if hasVal {
					printErr(fmt.Sprintf("The argument '--%s' does not take a value", name),
						fmt.Sprintf("%s --%s", progName(), name))
				}
				p.flags[fs.Long] = true
				p.provided[fs.Long] = true
				i++
				continue
			}
			if os := findOptByLong(name); os != nil {
				if !hasVal {
					if i+1 >= len(args) {
						printErr(fmt.Sprintf("The argument '--%s <%s>' requires a value but none was supplied", name, os.ValName),
							fmt.Sprintf("%s --%s <%s>", progName(), name, os.ValName))
					}
					val = args[i+1]
					i += 2
				} else {
					i++
				}
				p.options[os.Long] = val
				p.provided[os.Long] = true
				continue
			}
			// Unknown long option
			suggestion := suggest(name)
			msg := fmt.Sprintf("Found argument '--%s' which wasn't expected, or isn't valid in this context", name)
			if suggestion != "" {
				msg += "\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m" + suggestion + "\x1b[0m?"
			}
			printErr(msg, currentUsage(p))
		} else if len(a) > 1 && a[0] == '-' && a != "-" && !isNegativeNumber(a) {
			// short option(s)
			consumed := false
			j := 1
			for j < len(a) {
				c := a[j]
				if fs := findFlagByShort(c); fs != nil {
					if fs.Long == "help" {
						fmt.Print(renderHelp())
						os.Exit(0)
					}
					if fs.Long == "version" {
						fmt.Println(versionStr)
						os.Exit(0)
					}
					p.flags[fs.Long] = true
					p.provided[fs.Long] = true
					j++
					continue
				}
				if os := findOptByShort(c); os != nil {
					// Consume the rest of the string or next arg as value.
					var val string
					if j+1 < len(a) {
						rest := a[j+1:]
						// Handle -X=VAL
						if rest[0] == '=' {
							val = rest[1:]
						} else {
							val = rest
						}
					} else {
						if i+1 >= len(args) {
							printErr(fmt.Sprintf("The argument '-%c <%s>' requires a value but none was supplied", c, os.ValName),
								fmt.Sprintf("%s -%c <%s>", progName(), c, os.ValName))
						}
						val = args[i+1]
						i++
					}
					p.options[os.Long] = val
					p.provided[os.Long] = true
					consumed = true
					break
				}
				// Unknown short flag
				printErr(fmt.Sprintf("Found argument '-%c' which wasn't expected, or isn't valid in this context", c), currentUsage(p))
			}
			_ = consumed
			i++
			continue
		} else {
			// positional
			p.input = append(p.input, a)
			i++
		}
	}
	return p
}

func isNegativeNumber(s string) bool {
	// Clap rejects args like -1, -3.5 as "unexpected argument" not as a positional.
	// So we return false to force error path when any -X doesn't match a known option.
	return false
}

// suggest returns a suggestion for an unknown long option name, if any.
func suggest(name string) string {
	best := ""
	bestScore := -1
	for _, o := range optionSpecs {
		if strings.HasPrefix(o.Long, name) || strings.Contains(o.Long, name) {
			s := len(name)
			if s > bestScore {
				bestScore = s
				best = o.Long
			}
		}
	}
	for _, o := range flagSpecs {
		if strings.HasPrefix(o.Long, name) || strings.Contains(o.Long, name) {
			s := len(name)
			if s > bestScore {
				bestScore = s
				best = o.Long
			}
		}
	}
	return best
}

// currentUsage returns a USAGE line suitable for error output, reflecting
// currently-required options.
func currentUsage(p *Parsed) string {
	// Minimal, consistent with clap's behavior: show program + required opts.
	parts := []string{progName()}
	// Include options that have been provided so far (after some).
	if p != nil {
		// preserve order as defined in optionSpecs
		for _, o := range optionSpecs {
			if p.provided[o.Long] {
				parts = append(parts, "--"+o.Long+" <"+o.ValName+">")
			}
		}
	}
	return strings.Join(parts, " ")
}

// --- Duration parsing (humantime-like) ---

type durationPair struct {
	unit string
	val  time.Duration
}

var durUnits = []durationPair{
	{"nsec", time.Nanosecond}, {"ns", time.Nanosecond},
	{"usec", time.Microsecond}, {"us", time.Microsecond},
	{"msec", time.Millisecond}, {"ms", time.Millisecond},
	{"seconds", time.Second}, {"second", time.Second}, {"sec", time.Second}, {"s", time.Second},
	{"minutes", time.Minute}, {"minute", time.Minute}, {"min", time.Minute}, {"m", time.Minute},
	{"hours", time.Hour}, {"hour", time.Hour}, {"hr", time.Hour}, {"h", time.Hour},
	{"days", 24 * time.Hour}, {"day", 24 * time.Hour}, {"d", 24 * time.Hour},
	{"weeks", 7 * 24 * time.Hour}, {"week", 7 * 24 * time.Hour}, {"w", 7 * 24 * time.Hour},
	{"months", 30*24*time.Hour + 10*time.Hour + 30*time.Minute}, {"month", 30*24*time.Hour + 10*time.Hour + 30*time.Minute}, {"M", 30*24*time.Hour + 10*time.Hour + 30*time.Minute},
	{"years", 365*24*time.Hour + 6*time.Hour}, {"year", 365*24*time.Hour + 6*time.Hour}, {"y", 365*24*time.Hour + 6*time.Hour},
}

// parseDuration parses a humantime-style duration.
// Errors: "value was empty", "expected number at N", "unknown unit at N-M", "invalid character at N".
func parseDuration(s string) (time.Duration, error) {
	// Require at least one non-whitespace char
	allSpace := true
	for _, r := range s {
		if r != ' ' && r != '\t' {
			allSpace = false
			break
		}
	}
	if allSpace {
		return 0, fmt.Errorf("value was empty")
	}
	var total time.Duration
	i := 0
	n := len(s)
	for i < n {
		// skip whitespace
		for i < n && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		if i >= n {
			break
		}
		if !(s[i] >= '0' && s[i] <= '9') {
			return 0, fmt.Errorf("expected number at %d", i)
		}
		// parse number
		numStart := i
		for i < n && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		if i < n && (s[i] != ' ' && s[i] != '\t' && !isLetter(s[i])) {
			return 0, fmt.Errorf("invalid character at %d", i)
		}
		numStr := s[numStart:i]
		num, err := strconv.ParseUint(numStr, 10, 64)
		if err != nil {
			return 0, fmt.Errorf("expected number at %d", numStart)
		}
		// skip whitespace before unit
		for i < n && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		// parse unit
		unitStart := i
		for i < n && isLetter(s[i]) {
			i++
		}
		unitEnd := i
		unit := s[unitStart:unitEnd]
		// look up unit
		var d time.Duration
		found := false
		for _, up := range durUnits {
			if up.unit == unit {
				d = up.val
				found = true
				break
			}
		}
		if !found {
			return 0, fmt.Errorf("unknown unit at %d-%d", unitStart, unitEnd)
		}
		total += time.Duration(num) * d
	}
	return total, nil
}

func isLetter(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}

// --- Timestamp parsing ---

// Accepted formats (UTC):
//   2006-01-02 15:04:05
//   2006-01-02T15:04:05
//   2006-01-02T15:04:05Z
//   2006-01-02 15:04:05.999999
//   2006-01-02T15:04:05.999999
//   2006-01-02T15:04:05.999999Z
var timeFormats = []string{
	"2006-01-02 15:04:05",
	"2006-01-02T15:04:05",
	"2006-01-02T15:04:05Z",
	"2006-01-02 15:04:05.000000000",
	"2006-01-02T15:04:05.000000000",
	"2006-01-02T15:04:05.000000000Z",
	"2006-01-02 15:04:05.999999999",
	"2006-01-02T15:04:05.999999999",
	"2006-01-02T15:04:05.999999999Z",
}

func parseTimestamp(s string) (time.Time, error) {
	for _, f := range timeFormats {
		if t, err := time.ParseInLocation(f, s, time.UTC); err == nil {
			return t, nil
		}
	}
	return time.Time{}, fmt.Errorf("timestamp format is invalid")
}

// --- Float/Numeric parsing for count-by/offset/num ---

// parseNum: returns float value, and the count of decimals in the source string (0 if none).
func parseCountBy(s string) (float64, int, error) {
	v, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, 0, fmt.Errorf("invalid float literal")
	}
	// Compute the number of digits between '.' and 'e'/'E' (or end).
	precision := 0
	if dot := strings.IndexByte(s, '.'); dot >= 0 {
		j := dot + 1
		for j < len(s) && s[j] >= '0' && s[j] <= '9' {
			j++
		}
		precision = j - (dot + 1)
	}
	return v, precision, nil
}

func parseFloat(s string) (float64, error) {
	v, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid float literal")
	}
	return v, nil
}

// formatCount formats a counter value given precision.
func formatCount(v float64, precision int) string {
	// Rust's f64 default formatting rounds ties to even when precision is limited.
	// Go's %.0f rounds ties away from zero, so for precision 0 we need banker's rounding.
	if precision == 0 {
		return formatBankers(v)
	}
	return strconv.FormatFloat(v, 'f', precision, 64)
}

// formatBankers returns the integer representation with banker's rounding (ties to even).
func formatBankers(v float64) string {
	if math.IsNaN(v) {
		return "NaN"
	}
	if math.IsInf(v, 1) {
		return "inf"
	}
	if math.IsInf(v, -1) {
		return "-inf"
	}
	// round-half-to-even
	rounded := math.RoundToEven(v)
	// Format without decimals
	return strconv.FormatFloat(rounded, 'f', 0, 64)
}

// --- Main ---

func main() {
	p := parseArgs()
	if len(p.input) == 0 {
		fmt.Println("No command supplied, exiting.")
		return
	}

	// Parse every (duration) — must succeed; default is "1us".
	every, err := parseDuration(p.options["every"])
	if err != nil {
		printErr(fmt.Sprintf("Invalid value for '--every <every>': %s", err.Error()), "")
	}

	// Parse for-duration if provided.
	var forDur time.Duration
	hasForDur := false
	if p.provided["for-duration"] {
		forDur, err = parseDuration(p.options["for-duration"])
		if err != nil {
			printErr(fmt.Sprintf("Invalid value for '--for-duration <for_duration>': %s", err.Error()), "")
		}
		hasForDur = true
	}

	// Parse count-by
	countBy, precision, err := parseCountBy(p.options["count-by"])
	if err != nil {
		printErr(fmt.Sprintf("Invalid value for '--count-by <count_by>': %s", err.Error()), "")
	}
	// Parse offset
	offset, err := parseFloat(p.options["offset"])
	if err != nil {
		printErr(fmt.Sprintf("Invalid value for '--offset <offset>': %s", err.Error()), "")
	}

	// Parse num
	hasNum := false
	var numIters int64
	if p.provided["num"] {
		numf, err := strconv.ParseFloat(p.options["num"], 64)
		if err != nil {
			printErr("Invalid value for '--num <num>': invalid float literal", "")
		}
		hasNum = true
		numIters = int64(numf) // truncate toward zero
	}

	// Parse until-time
	hasUntilTime := false
	var untilTime time.Time
	if p.provided["until-time"] {
		untilTime, err = parseTimestamp(p.options["until-time"])
		if err != nil {
			printErr(fmt.Sprintf("Invalid value for '--until-time <until_time>': %s", err.Error()), "")
		}
		hasUntilTime = true
	}

	// Parse until-error (integer exit code)
	hasUntilError := false
	var untilErrorCode int64
	if p.provided["until-error"] {
		v, err := strconv.ParseInt(p.options["until-error"], 10, 64)
		if err != nil {
			printErr("Invalid value for '--until-error <until_error>': invalid digit found in string", "")
		}
		untilErrorCode = v
		hasUntilError = true
	}

	// Compile until-match regex
	var untilMatchRe *regexp.Regexp
	if p.provided["until-match"] {
		r, err := regexp.Compile(p.options["until-match"])
		if err != nil {
			printErr(fmt.Sprintf("Invalid value for '--until-match <until_match>': %s", err.Error()), "")
		}
		untilMatchRe = r
	}

	// Collect items list from --for and --stdin
	var items []string
	if p.provided["for"] {
		items = append(items, strings.Split(p.options["for"], ",")...)
	}
	if p.flags["stdin"] {
		// Read lines from stdin
		rd := bufio.NewReader(os.Stdin)
		for {
			line, err := rd.ReadString('\n')
			if len(line) > 0 {
				if strings.HasSuffix(line, "\n") {
					line = line[:len(line)-1]
				}
				items = append(items, line)
			}
			if err != nil {
				break
			}
		}
	}
	hasItems := p.provided["for"] || p.flags["stdin"]

	// Build command string (positional args joined with space, passed to sh -c)
	cmdStr := strings.Join(p.input, " ")

	// Flags
	onlyLast := p.flags["only-last"]
	summary := p.flags["summary"]
	untilChanges := p.flags["until-changes"]
	untilSame := p.flags["until-same"]
	untilFail := p.flags["until-fail"]
	untilSuccess := p.flags["until-success"]
	untilContainsSet := p.provided["until-contains"]
	untilContains := p.options["until-contains"]
	errorDuration := p.flags["error-duration"]

	// Loop
	startTime := time.Now()
	var totalRuns int64
	var successes int64
	var failures []int
	var lastOutput string
	prevOutput := ""
	havePrev := false
	timedOut := false

	var i int64
	for {
		// Check stop conditions BEFORE running
		if hasNum && i >= numIters {
			break
		}
		if hasItems && !hasNum && i >= int64(len(items)) {
			break
		}
		if hasForDur && time.Since(startTime) >= forDur {
			timedOut = true
			break
		}
		if hasUntilTime && !time.Now().Before(untilTime) {
			timedOut = true
			break
		}

		// Determine item
		item := ""
		if len(items) > 0 {
			if i < int64(len(items)) {
				item = items[i]
			} else {
				item = items[len(items)-1]
			}
		}

		// Compute counter value
		counterVal := offset + countBy*float64(i)
		countStr := formatCount(counterVal, precision)

